import * as D from './domain-27ca4e179461.mjs';

export function homeView(state,ui,h){
 const {e,button,duration,clock,longDate,compositionCard,onboardingBanner,timeline,planCard,phoneCard}=h;
 const date=D.dateKey(Date.now(),state.timeZone),stats=D.summarize(state,date,date),r=state.running,start=D.dayStart(date,state.timeZone),end=D.dayStart(D.addDays(date,1),state.timeZone);
 const plan=state.plans.find(p=>p.focus&&p.startDate<=date&&p.endDate>=date),recent=state.sessions.filter(s=>s.confirmation!=='pending'&&s.start<end&&s.end>start).sort((a,b)=>b.end-a.end)[0];
 const drafts=(ui.drafts||[]).filter(d=>d.kind==='records');
 const recentStart=recent?Math.max(start,recent.start):0,recentEnd=recent?Math.min(end,recent.end):0;
 return `<section class="heading compact-heading"><div><h1>今日</h1><p>${longDate(date)}</p></div></section>${onboardingBanner(state)}
 <div class="home-grid"><section class="card home-timer" id="home-timer"><div class="section-title"><h2>计时</h2><span class="muted">${r?clock(r.start,state.timeZone)+' 开始':'从现在开始'}</span></div>
 <div class="timer-now"><div><strong>${r?e(r.name):'此刻，想做什么？'}</strong><div class="timer-digits" data-live>${r?'00:00:00':'00:00'}</div></div><div class="timer-actions">${button('choose-activity',r?'切换活动':'开始记录','primary')}${r?button('stop','停止','secondary'):''}</div></div>
 ${r?`<div class="context-controls"><span>情境：${e(state.contextSpans.find(c=>c.end===null)?.name||'未设置')}</span>${button('current-context','设置 / 结束','text-button')}${ui.nativeStatus?.available&&state.settings.phone?.enabled?button('current-phone-mode',r.phoneMode==='focus'?'专注模式':'并行模式','text-button'):''}</div>`:''}
 ${r?`<div class="inline-actions">${button('forgot-switch','刚才忘了切换','text-button')}${button('timer-reminder','预计结束提醒','text-button')}</div>${r.needsReview?`<details class="pending-list"><summary>这段有待核对的时间</summary><p>运行曾中断，未确认尾段暂不计入正式时长和成长。可以先切换或停止，稍后整理。</p>${button('recovery','确认到现在／确定结束','secondary')}${button('forgot-switch','整理这段','text-button')}</details>`:''}`:''}
 ${state.sessions.some(s=>s.confirmation==='pending')?`<details class="pending-list"><summary>稍后核对 · ${state.sessions.filter(s=>s.confirmation==='pending').length}段</summary>${state.sessions.filter(s=>s.confirmation==='pending').map(s=>`<div class="weekly-row"><strong>${e(s.name)}</strong><p>${D.dateKey(s.start,state.timeZone)} ${clock(s.start,state.timeZone)}—${clock(s.end,state.timeZone)}</p>${button('confirm-pending','这整段确实在做','secondary',s.id)}${button('organize-pending','整理／部分留白','text-button',s.id)}${button('pending-blank','整段留白','text-button',s.id)}</div>`).join('')}</details>`:''}
 <div class="home-quick"><div class="section-title"><h3>常用活动</h3><div>${button('choose-activity','全部活动','text-button')}${button('manage-activities','管理','text-button')}</div></div><div class="home-quick-list">${state.activities.filter(a=>a.favorite&&!a.archived).map(a=>`<button type="button" class="secondary ${r?.activityId===a.id?'selected':''}" data-action="quick-start" data-id="${e(a.id)}"><span class="color-dot" style="background:${e(a.color)}"></span>${e(a.name)}</button>`).join('')||'<p class="muted">可在全部活动中选择，或将常用项设为收藏。</p>'}</div></div>
 ${plan?`<details id="today-focus" data-preserve class="home-focus"><summary>今日重点 · ${e(plan.title)}</summary>${planCard(state,plan,true)}${button('stage-overview','查看阶段总览','text-button',plan.id)}</details>`:`<div class="home-focus">${button('new-plan','设置今日重点','text-button')}</div>`}</section>
 <section class="card home-footprint"><div class="section-title"><h2>今天的足迹</h2><span class="muted">已记录 ${duration(stats.totalMinutes)}</span></div>${compositionCard(state,date,{e,duration,num:h.num})}<div class="day-ribbon" aria-label="今日时间分布">${stats.rows.map(s=>`<span style="left:${(s.start-start)/864000}%;width:${Math.max(0.12,(s.end-s.start)/864000)}%;background:${e(s.color)}" title="${e(s.name)}"></span>`).join('')}</div><div class="ribbon-scale"><span>00:00</span><span>12:00</span><span>24:00</span></div></section>
 <section class="card recent-record" id="recent-record"><div class="section-title"><h2>最近一段</h2>${recent?button('edit-session','修正','secondary',recent.id):''}</div>${recent?`<strong>${e(recent.name)} · ${duration((recentEnd-recentStart)/60000)}</strong><p>${clock(recentStart,state.timeZone,true)}—${clock(recentEnd,state.timeZone,true)}${recent.start<start?' · 今日部分':''}</p>`:'<p class="muted">今天还没有已结束的活动。</p>'}</section>
 ${phoneCard(state,{e,duration,clock,date},true)}</div>
 <details id="today-timeline" data-preserve class="card"><summary>一天的经过 · 完整时间线${drafts.length?' · '+drafts.length+'份整理草稿':''}</summary><div class="section-title"><h2>今日记录</h2><div class="inline-actions">${button('add-session','补记','secondary')}${button('organize-range','整理范围','secondary')}${button('history-context','调整情境','secondary')}${button('to-memory','回看图文 ↗','text-button')}</div></div>${timeline(state,date)}${drafts.map(d=>button('resume-range','继续整理草稿','secondary',d.id)).join('')}</details>`;
}

